'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var pow = require( '@stdlib/math/base/special/pow' );
var Float32Array = require( '@stdlib/array/float32' );
var Float64Array = require( '@stdlib/array/float64' );
var Complex64 = require( '@stdlib/complex/float32/ctor' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var realf = require( '@stdlib/complex/float32/real' );
var imagf = require( '@stdlib/complex/float32/imag' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );
var reinterpret64 = require( '@stdlib/strided/base/reinterpret-complex64' );
var reinterpret128 = require( '@stdlib/strided/base/reinterpret-complex128' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var factory = require( './../lib' );


// FUNCTIONS //

/**
* Creates a benchmark function for Complex128Array.
*
* @private
* @param {PositiveInteger} len - array length
* @returns {Function} benchmark function
*/
function createBenchmark128( len ) {
	var Complex128Array;

	Complex128Array = factory( 'complex128', Float64Array, Complex128, real, imag, reinterpret128 );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var arr;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			arr = new Complex128Array( len );
			if ( arr.length !== len ) {
				b.fail( 'unexpected length' );
			}
		}
		b.toc();
		if ( !(arr instanceof Complex128Array) ) {
			b.fail( 'should return an instance' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}

/**
* Creates a benchmark function for Complex64Array.
*
* @private
* @param {PositiveInteger} len - array length
* @returns {Function} benchmark function
*/
function createBenchmark64( len ) {
	var Complex64Array;

	Complex64Array = factory( 'complex64', Float32Array, Complex64, realf, imagf, reinterpret64 );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var arr;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			arr = new Complex64Array( len );
			if ( arr.length !== len ) {
				b.fail( 'unexpected length' );
			}
		}
		b.toc();
		if ( !(arr instanceof Complex64Array) ) {
			b.fail( 'should return an instance' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var len;
	var min;
	var max;
	var f;
	var i;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( i = min; i <= max; i++ ) {
		len = pow( 10, i );
		f = createBenchmark128( len );
		bench( format( '%s::complex128,len=%d', pkg, len ), f );
	}
	for ( i = min; i <= max; i++ ) {
		len = pow( 10, i );
		f = createBenchmark64( len );
		bench( format( '%s::complex64,len=%d', pkg, len ), f );
	}
}

main();
